    pub fn parse(value: []const u8) ?AgentRemoteDevTaskStatus {
        if (std.mem.eql(u8, value, "queued")) return .queued;
        if (std.mem.eql(u8, value, "running")) return .running;
        if (std.mem.eql(u8, value, "streaming")) return .streaming;
        if (std.mem.eql(u8, value, "pushed")) return .pushed;
        if (std.mem.eql(u8, value, "pr_open")) return .pr_open;
        if (std.mem.eql(u8, value, "pr_merged")) return .pr_merged;
        if (std.mem.eql(u8, value, "pr_closed")) return .pr_closed;
        if (std.mem.eql(u8, value, "done")) return .done;
        if (std.mem.eql(u8, value, "failed")) return .failed;
        if (std.mem.eql(u8, value, "cancelled")) return .cancelled;
        return null;
